SourceCode.Declaration:
/// <summary>
/// The service class for sales order cancel process.
/// </summary>
class METSalesOrderLineService extends SysOperationServiceBase
{
    #OCCRetryCount
    
}

Method.Source:
    /// <summary>
    /// cancels the sales order.
    /// </summary>
    /// <param name="salesOrderLineCancelRequest">
    /// The contract instance
    /// </param>
    /// <returns>
    /// The response <c>METSalesOrderCancelResponseContract</c>
    /// </returns>
    public METSalesOrderLineCancelResponseContract cancelSalesOrderLine(METSalesOrderLineCancelRequestContract salesOrderLineCancelRequest)
    {
        METProcessingStatus cancelResult;
        Description255      cancelMessage;

        [cancelResult, cancelMessage] = this.processCancelSalesOrderLine(salesOrderLineCancelRequest);
        
        return METSalesOrderLineCancelResponseContract::newFromParameters(cancelResult, cancelMessage);
    }

    /// <summary>
    /// cancels the sales order line
    /// </summary>
    /// <param name="_salesOrderLineCancelRequest">The contract instance</param>
    /// <returns>Container of Results</returns>
    public container processCancelSalesOrderLine(METSalesOrderLineCancelRequestContract _salesOrderLineCancelRequest)
    {
        METProcessingStatus cancelResult;
        Description255      cancelMessage;
        SalesLine           salesLine;
        SalesId             salesId;
        LineNum             lineNum;
        DataAreaId          dataAreaId;

        salesId     = _salesOrderLineCancelRequest.parmSalesId();
        lineNum     = _salesOrderLineCancelRequest.parmLineNum();
        dataAreaId  = _salesOrderLineCancelRequest.parmDataAreaId();
        
        try
        {
            ttsbegin;

            changecompany(dataAreaId)
            {
                salesLine = SalesLine::find(salesId, lineNum, true);
        
                if(!salesLine.RecId)
                {
                    cancelResult = METProcessingStatus::Error;
                    cancelMessage = "@MET:SalesOrderLineNotFound";
                }
                else if(salesLine.SalesStatus != SalesStatus::Backorder)
                {
                    cancelResult = METProcessingStatus::Error;
                    cancelMessage = "@MET:SalesOrderLineNotOpen";
                }
                else
                {
                    //code copied from FormSalesUpdateRemain.CloseOk()
                
                    MCRSalesOrderCancellation mcrSalesOrderCancellation;

                    if (isConfigurationkeyEnabled(configurationKeyNum(MCRCallCenter)))
                    {
                        mcrSalesOrderCancellation = new MCRSalesOrderCancellation();
                        mcrSalesOrderCancellation.preCancel(SalesTable::find(salesLine.SalesId));
                    }

                    SalesUpdateRemain salesUpdateRemain = SalesUpdateRemain::construct();
                    boolean updated = salesUpdateRemain.updateDeliverRemainder(salesLine, 0, 0);

                    if (updated)
                    {
                        if (isConfigurationkeyEnabled(configurationKeyNum(MCRCallCenter)))
                        {
                            SalesTable salesTable;
                    
                            if (salesLine.SalesStatus == SalesStatus::Canceled)
                            {
                                SalesLine salesLineLocal = SalesLine::findRecId(salesLine.RecId);
                                mcrSalesOrderCancellation.postCancelLine(salesLineLocal);
                                
                                // Additional find in case the status changed in the postCancelLine method
                                salesTable = SalesTable::find(salesLine.SalesId,true);

                                if (salesTable.SalesStatus == SalesStatus::Canceled)
                                {
                                    mcrSalesOrderCancellation.postCancelOrder(salesTable);
                                }
                            }

                            // Additional find in case the status changed in the postCancelLine or postCancelOrder method
                            salesTable = SalesTable::find(salesLine.SalesId, true);
                            
                            // If sales order is paid by loyalty create the refund loyalty lines and post them as part of this process
                            if (salesTable.SalesStatus != SalesStatus::Canceled)
                            {
                                mcrSalesOrderCancellation.RefundLoyaltyPointsForSalesLine(salesTable, salesLine);
                            }
                            
                            mcrSalesOrderCancellation.postCancelAdjPayment(salesTable);
                        }

                        cancelResult = METProcessingStatus::Success;
                        cancelMessage = "@MET:SalesOrderLineCancellationSuccessful";
                    }
                    else
                    {
                        cancelResult = METProcessingStatus::Error;
                        cancelMessage = "@MET:SalesOrderLineCancellationFailed";
                    }
                }
                   
                if(cancelResult == METProcessingStatus::Error)
                {
                    throw error(cancelMessage);
                }
                
                ttscommit;
            }
        }
        catch (Exception::Deadlock)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    error("@MET:SalesCancelDeadlock");
                    throw Exception::Deadlock;
                }
                else
                {
                    retry;
                }
            }
            else
            {
                error("@MET:SalesCancelDeadlock");
                throw Exception::Deadlock;
            }
        }
        catch (Exception::UpdateConflict)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    error("@MET:SalesCancelUpdateConflict");
                    throw Exception::UpdateConflictNotRecovered;
                }
                else
                {                            
                    retry;
                }
            }
            else
            {
                error("@MET:SalesCancelUpdateConflict");
                throw Exception::UpdateConflict;
            }
        }
        
        return [cancelResult, cancelMessage];
       
    }
